;## kw_sgnv
;kw_sgnv, <var>, <destvar>  - -1, 0 or 1
kw_sgnv:
			movea.l (sp)+, a0
			moveq #0, d0
			move.w (a0), d1
			beq kw_sgn_st
			moveq #1, d0
			tst.w d1
			bpl kw_sgn_st
			moveq #-1, d0
kw_sgn_st:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

